import math
values=[0.0,-0.0,1.0,-1.0,1e-300,-1e-300,float('inf'),float('-inf'),float('nan')]
for a in values:
 for b in [2.0,-2.0,0.1,-0.1,float('inf'),float('-inf'),float('nan')]:
  q,r=divmod(a,b)
  print(q,r,math.copysign(1.0,q) if not math.isnan(q) else 0.0,math.copysign(1.0,r) if not math.isnan(r) else 0.0,a//b,a%b)

for b in [0.0,-0.0]:
 for operation in [lambda:1.0//b,lambda:1.0%b,lambda:divmod(1.0,b)]:
  try:operation()
  except ZeroDivisionError:print('zero')

value=1<<2000
for operation in [lambda:value//0.0,lambda:value%0.0,lambda:divmod(value,0.0),lambda:1.0//value,lambda:1.0%value,lambda:divmod(1.0,value)]:
 try:operation()
 except OverflowError:print('overflow')
 except ZeroDivisionError:print('zero')

for offset in [1<<971,(1<<970)+1,1<<970,(1<<970)-1]:
 for sign in [-1,1]:
  try:print(sign*((1<<1024)-offset)/1)
  except OverflowError:print('overflow')

import operator
value=1<<2000
print(operator.truediv(value,value));result=value;result/=value;print(result)
for operation in [lambda:value/0,lambda:value/0.0]:
 try:operation()
 except ZeroDivisionError:print('zero')
 except OverflowError:print('overflow')

import math
value=1<<20000
for a,b in [(1,value),(-1,value),(0,-value)]:
 result=a/b;print(result,math.copysign(1.0,result))
try:value/1
except OverflowError:print('overflow')

import operator
for operation in [lambda:2.0**1024,lambda:pow(2.0,1024),lambda:operator.pow(2.0,1024),lambda:(1<<2000)**-1,lambda:0**-(1<<2000),lambda:0.0**-1]:
 try:operation()
 except OverflowError:print('overflow')
 except ZeroDivisionError:print('zero')

import math
for a in [0.0,-0.0,1.0,-1.0,2.0,-2.0,float('inf'),float('-inf'),float('nan')]:
 for b in [float('-inf'),-3.0,-0.5,0.0,0.5,3.0,float('inf'),float('nan')]:
  try:
   result=a**b
   if isinstance(result,complex):print('complex')
   else:print(result,math.copysign(1.0,result) if not math.isnan(result) else 0.0)
  except ZeroDivisionError:print('zero')
  except OverflowError:print('overflow')

import operator
for operation in [lambda:0<<-1,lambda:0>>-1,lambda:1<<-1,lambda:-7>>-1,lambda:operator.lshift(0,-(1<<40))]:
 try:operation()
 except ValueError:print('negative')

import math
for a,b in [(0.0,float('-inf')),(-0.0,float('-inf')),(2.0,1024.0),(-2.0,0.5),(float('inf'),-1.0)]:
 try:print(math.pow(a,b))
